     "time": "08-28 13:44",
     "ts": 1787895863,
     "summary": "真正的经济复兴，不是简单回归凯恩斯或新自由主义，而是重建支撑大众创造力的文化土壤与制度环境；一个国家的繁荣，不取决于它积累了多少无生命的财富，也不取决于它拥有多少不可一世的巨头企业，而取决于它能否让亿万普通人拥有发挥想象力、迎接挑战与实现自我价值的制度舞台；真正的经济活力、经济奇迹，孕育在千千万万没有特权、没有背书，却渴望改善自身命运的普通人之中。",
